  return (
    <form className="space-y-4" onSubmit={form.handleSubmit(onSubmit)}>
      <div>
        <Label>Name</Label>
        <Input {...form.register("name")} />
      </div>

      <div>
        <Label>Email</Label>
        <Input type="email" {...form.register("email")} />
      </div>

